interface Logo {
  x: number;
  y: number;
  vx: number;
  vy: number;
  baseVx: number;
  baseVy: number;
  size: number;
  opacity: number;
  rotation: number;
  rotSpeed: number;
  logoIdx: number;
}

const LOGO_COUNT = 160;
const REPEL_RADIUS = 150;
const REPEL_STRENGTH = 8;

export function FloatingLogos() {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const logosRef = useRef<Logo[]>([]);
  const mouseRef = useRef({ x: -9999, y: -9999 });
  const animFrameRef = useRef<number>(0);
  const scrollYRef = useRef(0);

  const initLogos = useCallback((w: number, h: number) => {
    const pageHeight = document.documentElement.scrollHeight;
    const logos: Logo[] = [];
    for (let i = 0; i < LOGO_COUNT; i++) {
      const speed = 0.15 + Math.random() * 0.35;
      const angle = Math.random() * Math.PI * 2;
      logos.push({
        x: Math.random() * w,
        y: Math.random() * pageHeight,
        vx: Math.cos(angle) * speed,
        vy: Math.sin(angle) * speed,
        baseVx: Math.cos(angle) * speed,
        baseVy: Math.sin(angle) * speed,
        size: 20 + Math.random() * 22,
        opacity: 0.12 + Math.random() * 0.18,
        rotation: Math.random() * Math.PI * 2,
        rotSpeed: (Math.random() - 0.5) * 0.005,
        logoIdx: Math.floor(Math.random() * TECH_LOGOS.length),
      });
    }
    logosRef.current = logos;
  }, []);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d")!;

    const resize = () => {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
      if (logosRef.current.length === 0) {
        initLogos(canvas.width, canvas.height);
      }
    };
    resize();
    window.addEventListener("resize", resize);

    const onScroll = () => {
      scrollYRef.current = window.scrollY;
    };
    window.addEventListener("scroll", onScroll, { passive: true });
    onScroll();

    const onMouseMove = (e: MouseEvent) => {
      mouseRef.current.x = e.clientX;
      mouseRef.current.y = e.clientY;
    };
    window.addEventListener("mousemove", onMouseMove, { passive: true });

    const onMouseLeave = () => {
      mouseRef.current.x = -9999;
      mouseRef.current.y = -9999;
    };
    document.addEventListener("mouseleave", onMouseLeave);

    const draw = () => {
      const w = canvas.width;
      const h = canvas.height;
      const scrollY = scrollYRef.current;
      const mx = mouseRef.current.x;
      const my = mouseRef.current.y + scrollY; // mouse in page coords

      ctx.clearRect(0, 0, w, h);

      for (const logo of logosRef.current) {
        // Update position
        logo.x += logo.vx;
        logo.y += logo.vy;
        logo.rotation += logo.rotSpeed;

        // Wrap around
        const pageH = document.documentElement.scrollHeight;
        if (logo.x < -logo.size) logo.x = w + logo.size;
        if (logo.x > w + logo.size) logo.x = -logo.size;
        if (logo.y < -logo.size) logo.y = pageH + logo.size;
        if (logo.y > pageH + logo.size) logo.y = -logo.size;

        // Mouse repulsion (in page coordinates)
        const dx = logo.x - mx;
        const dy = logo.y - my;
        const dist = Math.sqrt(dx * dx + dy * dy);
        if (dist < REPEL_RADIUS && dist > 0) {
          const force = (1 - dist / REPEL_RADIUS) * REPEL_STRENGTH;
          logo.vx += (dx / dist) * force * 0.1;
          logo.vy += (dy / dist) * force * 0.1;
        }

        // Dampen back to base velocity
        logo.vx += (logo.baseVx - logo.vx) * 0.02;
        logo.vy += (logo.baseVy - logo.vy) * 0.02;

        // Only draw if visible on screen
        const screenY = logo.y - scrollY;
        if (screenY < -logo.size * 2 || screenY > h + logo.size * 2) continue;

        // Draw SVG logo as path
        const tech = TECH_LOGOS[logo.logoIdx];
        const s = logo.size;

        ctx.save();
        ctx.translate(logo.x, screenY);
        ctx.rotate(logo.rotation);
        ctx.globalAlpha = logo.opacity;

        // Parse viewBox
        const vbParts = tech.viewBox.split(" ").map(Number);
        const vbW = vbParts[2] || 24;
        const vbH = vbParts[3] || 24;
        const scale = s / Math.max(vbW, vbH);

        ctx.translate(-s / 2, -s / 2);
        ctx.scale(scale, scale);

        ctx.fillStyle = tech.color;
        for (const d of tech.paths) {
          const p = new Path2D(d);
          ctx.fill(p);
        }

        ctx.restore();
      }

      animFrameRef.current = requestAnimationFrame(draw);
    };

    animFrameRef.current = requestAnimationFrame(draw);

    return () => {
      cancelAnimationFrame(animFrameRef.current);
      window.removeEventListener("resize", resize);
      window.removeEventListener("scroll", onScroll);
      window.removeEventListener("mousemove", onMouseMove);
      document.removeEventListener("mouseleave", onMouseLeave);
    };
  }, [initLogos]);

  return (
    <canvas
      ref={canvasRef}
      className="fixed inset-0 z-[1] pointer-events-none"
      style={{ willChange: "transform" }}
    />
  );
}
